package state

import (
	"fmt"
	"slices"
	"strings"
	"time"

	"github.com/ckanner/flywheel/internal/decision"
)

// Collection controls are generated by Go from successful observations. They
// only defer reads or hand evidence to the analyst; they do not prove a finding.
type InvestigationControl struct {
	ActionID string   `json:"action-id"`
	Kind     string   `json:"kind"`
	Actions  []string `json:"actions"`
	Evidence []string `json:"evidence"`
}

type InvestigationDecisionEffect struct {
	InvestigationControl
	DecisionID    string `json:"decision-id"`
	Observations  int    `json:"observations"`
	BindingHash   string `json:"binding-hash"`
	CandidateHash string `json:"candidate-hash"`
	At            string `json:"at"`
}

func collectionControlID(kind, action string) string {
	return "jev-" + kind + "-" + PreparationHash(action)[:24]
}

func knownCollectionControl(st *PreparationState, id string) bool {
	if id == collectionControlID("finish", st.Contract.ID) {
		return true
	}
	for _, action := range st.Contract.Actions {
		if id == collectionControlID("defer", action.ID) {
			return true
		}
	}
	return false
}

// InvestigationControls supplies finite choices with concrete evidence. A read
// may be deferred only when each hypothesis has an untruncated successful
// observation from the same input candidate. Finishing additionally requires
// evidence for every hypothesis; stale observations never authorize a shortcut.
func InvestigationControls(st *PreparationState, candidateHash string) []InvestigationControl {
	done, evidence := map[string]bool{}, map[string][]string{}
	for _, observation := range st.Observations {
		done[observation.Invocation.ActionID] = true
		if observation.Status != "observed" || observation.Truncated || strings.TrimSpace(observation.Output) == "" || observation.Invocation.CandidateHash != candidateHash {
			continue
		}
		// An expected nonzero reproducer exit is useful evidence for the analyst,
		// but is not success evidence that can shorten the remaining collection.
		if e := observation.Execution; e != nil && (e.TimedOut || e.Cancelled || e.Signal != "" || (e.Kind == "run_command" && (e.ExitCode == nil || *e.ExitCode != 0 || e.Cleanup != "removed")) || (e.Kind == "http_read" && (e.HTTPStatus < 200 || e.HTTPStatus > 299))) {
			continue
		}
		for _, action := range st.Contract.Actions {
			if action.ID == observation.Invocation.ActionID {
				for _, hypothesis := range action.Hypotheses {
					evidence[hypothesis] = append(evidence[hypothesis], observation.Invocation.ID)
				}
			}
		}
	}
	for _, effect := range st.DecisionEffects {
		for _, id := range effect.Actions {
			done[id] = true
		}
	}
	controls := []InvestigationControl{}
	remaining := []string{}
	for _, action := range st.Contract.Actions {
		if done[action.ID] {
			continue
		}
		remaining = append(remaining, action.ID)
		citations := collectionEvidence(action.Hypotheses, evidence)
		if len(citations) > 0 {
			controls = append(controls, InvestigationControl{ActionID: collectionControlID("defer", action.ID), Kind: "defer", Actions: []string{action.ID}, Evidence: citations})
		}
	}
	hypotheses := []string{}
	for _, hypothesis := range st.Contract.Hypotheses {
		hypotheses = append(hypotheses, hypothesis.ID)
	}
	if citations := collectionEvidence(hypotheses, evidence); len(citations) > 0 && len(remaining) > 0 {
		controls = append([]InvestigationControl{{ActionID: collectionControlID("finish", st.Contract.ID), Kind: "finish", Actions: remaining, Evidence: citations}}, controls...)
	}
	return controls
}

func collectionEvidence(hypotheses []string, evidence map[string][]string) []string {
	citations := []string{}
	for _, hypothesis := range hypotheses {
		if len(evidence[hypothesis]) == 0 {
			return nil
		}
		for _, id := range evidence[hypothesis] {
			if !slices.Contains(citations, id) {
				citations = append(citations, id)
			}
		}
	}
	return citations
}

func validatePreparationEffects(st *PreparationState, started time.Time) error {
	previous, finished, used := 0, false, map[string]bool{}
	previousAt := started
	for i, effect := range st.DecisionEffects {
		at, err := time.Parse(time.RFC3339Nano, effect.At)
		if err != nil || at.Before(previousAt) || at.Sub(started).Milliseconds() > st.ElapsedMS || finished || used[effect.DecisionID] || effect.Observations < previous || effect.Observations > len(st.Observations) {
			return fmt.Errorf("invalid investigation collection history")
		}
		prefix := *st
		prefix.Observations, prefix.DecisionEffects = st.Observations[:effect.Observations], st.DecisionEffects[:i]
		for _, observation := range prefix.Observations {
			completed, _ := time.Parse(time.RFC3339Nano, observation.FinishedAt)
			if completed.After(at) {
				return fmt.Errorf("collection control cites future evidence")
			}
		}
		bound := false
		for _, control := range InvestigationControls(&prefix, effect.CandidateHash) {
			bound = bound || (PreparationHash(control) == effect.BindingHash && PreparationHash(control) == PreparationHash(effect.InvestigationControl))
		}
		matched := false
		for _, receipt := range st.Decisions {
			matched = matched || (receipt.DecisionID == effect.DecisionID && receipt.Status == "ok" && receipt.HTTPStatus == 200 && receipt.ActionID == effect.ActionID)
		}
		if !bound || !matched || st.Contract.Decision == nil || st.Contract.Decision.Policy.Mode != decision.Adopt {
			return fmt.Errorf("collection control lacks its approved evidence binding or decision")
		}
		for _, observation := range st.Observations[effect.Observations:] {
			if slices.Contains(effect.Actions, observation.Invocation.ActionID) {
				return fmt.Errorf("a deferred investigation action was executed")
			}
		}
		if st.Pending != nil && slices.Contains(effect.Actions, st.Pending.ActionID) {
			return fmt.Errorf("a deferred investigation action is pending")
		}
		if effect.Kind == "finish" && (effect.Observations != len(st.Observations) || (st.Status != "awaiting-report" && st.Status != "cancelled" && st.Report == nil)) {
			return fmt.Errorf("collection finish cannot resume evidence gathering")
		}
		used[effect.DecisionID], previous, finished = true, effect.Observations, effect.Kind == "finish"
		previousAt = at
	}
	return nil
}
